<template><view class="page"><view class="wrap"><MobileHeader title="工作台"/><view class="card account"><view class="avatar"><AppIcon name="user" :size="30" color="#294fdb"/></view><view><text class="welcome">{{ session.identity ? session.identity.user.nickname : '欢迎使用' }}</text><text class="muted">{{ session.identity ? '工作台' : '登录后使用公共服务' }}</text></view><view class="account-action" role="button" @tap="account">{{ session.identity ? '账户' : '登录' }}<AppIcon name="chevron-right" :size="16" color="#8791a4"/></view></view><view class="heading"><text class="section-title">公共服务</text></view><view class="services"><view v-for="item in services" :key="item.path" class="service" role="button" @tap="open(item.path)"><view class="service-icon"><AppIcon :name="item.icon" :size="25" color="#294fdb"/></view><text>{{ item.title }}</text><text class="muted">{{ item.subtitle }}</text></view></view><view class="heading"><text class="section-title">最近通知</text><text class="badge" role="button" @tap="open('/pages/notifications/index')">全部</text></view><view class="card"><view v-for="notice in notices" :key="notice.id" class="row" @tap="open('/pages/notifications/index')"><text>{{notice.templateContent}}</text><AppIcon name="chevron-right" :size="16" color="#8791a4"/></view><view v-if="!notices.length" class="empty">{{ session.identity?'暂无未读通知':'登录后查看通知' }}</view></view></view><TabBar current="workbench"/></view></template>
<script setup lang="ts">
import {ref} from 'vue';import {onShow} from '@dcloudio/uni-app';import MobileHeader from '@/components/MobileHeader.vue';import TabBar from '@/components/TabBar.vue';import AppIcon from '@/components/AppIcon.vue';import {client,session,requireSession} from '@/platform';
const services=[{title:'文件',subtitle:'上传与下载',icon:'apps',path:'/pages/files/index'},{title:'通知',subtitle:'消息与已读状态',icon:'notification',path:'/pages/notifications/index'},{title:'配置',subtitle:'公共参数',icon:'settings',path:'/pages/config/index'}];const notices=ref<any[]>([]);function account(){uni.navigateTo({url:'/pages/account/index'});}function open(url:string){if(requireSession())uni.navigateTo({url});}onShow(async()=>{notices.value=[];if(session.identity)try{notices.value=await client.request('GET','/admin-api/system/notify-message/get-unread-list?size=3');}catch{uni.showToast({title:'通知暂时不可用',icon:'none'});}});
</script>
<style scoped lang="scss">.page{min-height:100vh;background:#f7f8fc;padding-bottom:calc(110px + env(safe-area-inset-bottom))}.wrap{max-width:500px;margin:auto;padding:0 15px}.section-title{font-size:17px;font-weight:600}.card{background:#fff;border-radius:18px;padding:18px;margin-top:14px;box-shadow:0 6px 16px rgba(20,31,51,.06)}.row{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:14px 0;border-bottom:1px solid #eef1f6}.row:last-child{border:0}.muted{color:#8791a4;font-size:12px}.primary{margin-top:20px;background:#294fdb;color:white;border-radius:12px;font-size:14px}.field{padding:15px 0;border-bottom:1px solid #eef1f6}.field text{display:block;font-size:13px;color:#636e82;margin-bottom:10px}.field input{font-size:14px}.empty{padding:36px 0;text-align:center;color:#8791a4;font-size:14px}.badge{color:#294fdb;font-size:12px}.error{color:#d44545;font-size:13px;margin-top:12px}</style><style scoped>.account{display:flex;align-items:center;gap:12px}.avatar{width:56px;height:56px;border-radius:18px;background:#e8f0ff;display:flex;align-items:center;justify-content:center}.welcome{display:block;font-size:20px;font-weight:600;margin-bottom:6px}.account-action{margin-left:auto;display:flex;align-items:center;font-size:13px;color:#636e82}.heading{margin:26px 3px 0;display:flex;justify-content:space-between}.services{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:14px}.service{background:white;border-radius:18px;padding:18px 8px;display:flex;flex-direction:column;align-items:center;gap:10px;font-size:14px}.service-icon{width:46px;height:46px;background:#edf1ff;border-radius:15px;display:flex;align-items:center;justify-content:center}.service .muted{font-size:10px}</style>
